  "m.prOpened": "{folder}: \uCDA9\uB3CC\uD558\uB294 \uD3B8\uC9D1 \uB0B4\uC6A9\uC744 \uD480 \uB9AC\uD018\uC2A4\uD2B8\uB85C \uBCF4\uB0C8\uC2B5\uB2C8\uB2E4: {url}",
  "pi.title": "\uB2E4\uB978 \uAE30\uAE30\uC5D0\uC11C \uC4F0\uB294 \uD50C\uB7EC\uADF8\uC778 \uC124\uCE58",
  "pi.body": "\uC774 \uCEE4\uBBA4\uB2C8\uD2F0 \uD50C\uB7EC\uADF8\uC778\uB4E4\uC740 \uB2E4\uB978 \uAE30\uAE30\uC5D0\uC11C \uCF1C\uC838(\uB610\uB294 \uC5C5\uB370\uC774\uD2B8\uB418\uC5B4) \uC788\uC2B5\uB2C8\uB2E4. Vault Sync for Git\uC740 Obsidian \uCEE4\uBBA4\uB2C8\uD2F0 \uB514\uB809\uD130\uB9AC\uC5D0 \uB4F1\uB85D\uB41C \uB300\uB85C, \uAC01 \uD50C\uB7EC\uADF8\uC778\uC758 GitHub \uACF5\uC2DD \uB9B4\uB9AC\uC2A4\uC5D0\uC11C \uAC19\uC740 \uBC84\uC804\uC744 \uC5EC\uAE30\uC5D0 \uC124\uCE58\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
  "pi.list": "\uD50C\uB7EC\uADF8\uC778",
  "pi.install": "\uC124\uCE58",
  "pi.failed": "{name}\uC744(\uB97C) \uC124\uCE58\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4: {error}",
  "pi.done": "\uC124\uCE58\uB428: {list}. \uBD88\uB7EC\uC624\uB824\uBA74 Obsidian\uC744 \uB2E4\uC2DC \uC2DC\uC791\uD558\uC138\uC694(\uB610\uB294 \uAC01 \uD50C\uB7EC\uADF8\uC778\uC744 \uAED0\uB2E4\uAC00 \uCF1C\uC138\uC694).",
  "s.cfgInstall": "\uACF5\uC2DD \uB9B4\uB9AC\uC2A4\uC5D0\uC11C \uD50C\uB7EC\uADF8\uC778 \uCF54\uB4DC \uC124\uCE58",
  "s.cfgInstallDesc": "\uD50C\uB7EC\uADF8\uC778 \uCF54\uB4DC\uB97C \uB3D9\uAE30\uD654\uD558\uB294 \uB300\uC2E0, \uAC01 \uAE30\uAE30\uAC00 \uD50C\uB7EC\uADF8\uC778\uC758 \uACF5\uC2DD \uB9B4\uB9AC\uC2A4\uC5D0\uC11C \uAC19\uC740 \uBC84\uC804\uC744 \uC124\uCE58\uD569\uB2C8\uB2E4(\uD655\uC778 \uD6C4). \uD50C\uB7EC\uADF8\uC778 \uBC84\uC804\uC740 \uACC4\uC18D \uB3D9\uAE30\uD654\uB429\uB2C8\uB2E4. \uB354 \uC548\uC804\uD569\uB2C8\uB2E4. \uB204\uAD6C\uB3C4 \uC800\uC7A5\uC18C\uB97C \uD1B5\uD574 \uB0B4 \uAE30\uAE30\uC5D0 \uCF54\uB4DC\uB97C \uBC00\uC5B4 \uB123\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
  "s.branchDesc": "\uC774 \uBCF4\uAD00\uC18C\uAC00 \uB3D9\uAE30\uD654\uD558\uB294 \uBE0C\uB79C\uCE58\uC785\uB2C8\uB2E4. \uBC14\uAFB8\uBA74 \uC0C8\uB85C \uBE44\uAD50\uB97C \uC2DC\uC791\uD558\uBA70, \uC544\uBB34\uAC83\uB3C4 \uC0AD\uC81C\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
  "s.branchChoose": "\uC120\uD0DD",
  "s.branchIntro": "\uAE30\uC874 \uBE0C\uB79C\uCE58\uB97C \uACE0\uB974\uAC70\uB098, \uD604\uC7AC \uBE0C\uB79C\uCE58\uC5D0\uC11C \uC0C8 \uBE0C\uB79C\uCE58(\uC608: \uCD08\uC548 \uBE0C\uB79C\uCE58)\uB97C \uB9CC\uB4DC\uC138\uC694.",
  "s.branchNew": "\uC0C8 \uBE0C\uB79C\uCE58",
  "s.branchInvalid": "\uC601\uBB38\uC790, \uC22B\uC790, - _ . \uBC0F /\uB9CC \uC0AC\uC6A9\uD558\uC138\uC694.",
  "s.branchNoHead": "{branch} \uBE0C\uB79C\uCE58\uAC00 \uBE44\uC5B4 \uC788\uC5B4 \uC544\uC9C1 \uBD84\uAE30\uD560 \uB300\uC0C1\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.",
  "s.branchNone": "\uC544\uC9C1 \uBE0C\uB79C\uCE58\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
  "s.branchCurrent": "\uD604\uC7AC \uBE0C\uB79C\uCE58",
  "s.branchUse": "\uC0AC\uC6A9",
  "s.emptyFolders": "\uBE48 \uD3F4\uB354 \uC720\uC9C0",
  "s.emptyFoldersDesc": "\uD30C\uC77C\uC774 \uC5C6\uB294 \uD3F4\uB354\uB3C4 \uBAA8\uB4E0 \uAE30\uAE30\uC5D0 \uC720\uC9C0\uB429\uB2C8\uB2E4(.vault-sync/folders.json\uC5D0 \uAE30\uB85D). \uC885\uB2E8 \uAC04 \uC554\uD638\uD654\uAC00 \uCF1C\uC838 \uC788\uB294 \uB3D9\uC548\uC5D0\uB294 \uAEBC\uC9D1\uB2C8\uB2E4.",
  "s.battery": "\uBC30\uD130\uB9AC \uC808\uC57D \uBAA8\uB4DC",
  "s.batteryDesc": "\uC774 \uAE30\uAE30\uC5D0\uC11C\uB294 \uC8FC\uAE30\uC801 \uB3D9\uAE30\uD654\uC640 \uD3B8\uC9D1 \uD6C4 \uB3D9\uAE30\uD654\uB97C \uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC2DC\uC791\uD560 \uB54C, Obsidian\uC73C\uB85C \uB3CC\uC544\uC62C \uB54C, \uC218\uB3D9\uC73C\uB85C \uB3D9\uAE30\uD654\uD560 \uB54C \uB3D9\uAE30\uD654\uD569\uB2C8\uB2E4.",
  "s.pause": "\uC790\uB3D9 \uB3D9\uAE30\uD654 \uC77C\uC2DC \uC911\uC9C0",
  "s.pauseDesc": "\uC774 \uAE30\uAE30\uC5D0\uB9CC \uC801\uC6A9\uB429\uB2C8\uB2E4. \uC218\uB3D9 \uB3D9\uAE30\uD654\uB294 \uACC4\uC18D \uC791\uB3D9\uD569\uB2C8\uB2E4.",
  "s.pauseDescOn": "\uC774 \uAE30\uAE30\uC5D0\uC11C \uC790\uB3D9 \uB3D9\uAE30\uD654\uAC00 \uC77C\uC2DC \uC911\uC9C0\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.",
  "s.pauseUntilResumed": "\uB2E4\uC2DC \uC2DC\uC791\uD560 \uB54C\uAE4C\uC9C0",
  "s.author": "\uCEE4\uBC0B \uC791\uC131\uC790",
  "s.authorDesc": "\uCEE4\uBC0B\uC5D0 \uAE30\uB85D\uB418\uB294 \uC774\uB984\uACFC \uC774\uBA54\uC77C(\uB458 \uB2E4 \uD544\uC694). \uBE44\uC6CC \uB450\uBA74 \uD638\uC2A4\uD2B8\uAC00 \uD1A0\uD070\uC758 \uACC4\uC815\uC744 \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
  "s.authorName": "\uC774\uB984",
  "s.authorEmail": "\uC774\uBA54\uC77C",
  "s.hMirror": "\uBC31\uC5C5 \uBBF8\uB7EC",
  "s.mirrorIntro": "\uB3D9\uAE30\uD654\uD560 \uB54C\uB9C8\uB2E4 \uC774 \uBCF4\uAD00\uC18C\uB97C \uB450 \uBC88\uC9F8 \uC800\uC7A5\uC18C(\uC608: \uB2E4\uB978 \uD638\uC2A4\uD2B8)\uC5D0\uB3C4 \uC5C5\uB85C\uB4DC\uD569\uB2C8\uB2E4. \uD478\uC2DC \uC804\uC6A9\uC774\uBA70 \uBBF8\uB7EC\uC5D0\uC11C \uB2E4\uC2DC \uC77D\uC5B4 \uC624\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC885\uB2E8 \uAC04 \uC554\uD638\uD654\uB97C \uC0AC\uC6A9\uD558\uBA74 \uBBF8\uB7EC\uB3C4 \uC554\uD638\uD654\uB429\uB2C8\uB2E4.",
  "s.mirrorOn": "\uC774 \uBCF4\uAD00\uC18C \uBBF8\uB7EC\uB9C1",
  "s.mirrorToken": "\uBBF8\uB7EC \uD1A0\uD070",
  "s.mirrorTokenDesc": "\uBBF8\uB7EC \uC800\uC7A5\uC18C\uC758 \uC561\uC138\uC2A4 \uD1A0\uD070\uC785\uB2C8\uB2E4. \uC774 \uAE30\uAE30\uC5D0\uB9CC \uC800\uC7A5\uB429\uB2C8\uB2E4. \uBE44\uC6CC \uB450\uBA74 \uAC19\uC740 \uD638\uC2A4\uD2B8\uC778 \uACBD\uC6B0 \uAE30\uBCF8 \uD1A0\uD070\uC744 \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
  "s.mirrorIncomplete": "\uBA3C\uC800 \uBBF8\uB7EC\uB97C \uCF1C\uACE0 \uC18C\uC720\uC790\uC640 \uC800\uC7A5\uC18C\uB97C \uC785\uB825\uD558\uC138\uC694.",
  "s.mirrorOk": "\uBBF8\uB7EC\uC5D0 \uC5F0\uACB0\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4: {repo}",
