  "h.mirrorFailed": "\uBC31\uC5C5 \uBBF8\uB7EC {target} \uC2E4\uD328: {error}",
  "cmd.overwrite": "\uC800\uC7A5\uC18C\uB97C \uC774 \uAE30\uAE30\uC640 \uC77C\uCE58\uC2DC\uD0A4\uAE30",
  "ow.title": "\uC800\uC7A5\uC18C\uB97C \uC774 \uAE30\uAE30\uC640 \uC77C\uCE58\uC2DC\uD0A4\uAE30",
  "ow.body": "{host}\uC5D0 \uC0C8 \uCEE4\uBC0B \uD558\uB098\uB97C \uB9CC\uB4E4\uC5B4 \uC800\uC7A5\uC18C\uB97C \uC774 \uAE30\uAE30\uC640 \uB611\uAC19\uC774 \uB9CC\uB4ED\uB2C8\uB2E4. \uC774 \uD30C\uC77C\uB4E4\uC740 \uC5C5\uB85C\uB4DC\uB418\uACE0, \uC774 \uD30C\uC77C\uB4E4\uC740 \uC800\uC7A5\uC18C\uC5D0\uC11C \uC0AD\uC81C\uB429\uB2C8\uB2E4(\uAE30\uB85D\uC5D0\uB294 \uB0A8\uC2B5\uB2C8\uB2E4). \uD544\uC694\uD560 \uB54C \uB2E4\uC6B4\uB85C\uB4DC\uD558\uB3C4\uB85D {host}\uC5D0\uB9CC \uBCF4\uAD00\uB41C \uD30C\uC77C\uC740 \uADF8\uB300\uB85C \uB461\uB2C8\uB2E4. \uB2E4\uB978 \uAE30\uAE30\uC5D0\uB294 \uB2E4\uC74C \uB3D9\uAE30\uD654 \uB54C \uBC18\uC601\uB429\uB2C8\uB2E4.",
  "ow.upload": "\uC5C5\uB85C\uB4DC",
  "ow.confirm": "\uC77C\uCE58\uC2DC\uD0A4\uAE30",
  "ow.done": "\uC800\uC7A5\uC18C\uB97C \uC5C5\uB370\uC774\uD2B8\uD588\uC2B5\uB2C8\uB2E4: \uCEE4\uBC0B \uD558\uB098\uC5D0 \uBCC0\uACBD \uC0AC\uD56D {n}\uAC1C.",
  "ow.failed": "\uC800\uC7A5\uC18C\uB97C \uC5C5\uB370\uC774\uD2B8\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4: {error}",
  "m.clipboardFailed": "\uD074\uB9BD\uBCF4\uB4DC\uC5D0 \uBCF5\uC0AC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4: {error}",
