  "sb.soon": "1\uBD84 \uC774\uB0B4",
  "sb.nextTip": "\uB2E4\uC74C \uC608\uC57D \uB3D9\uAE30\uD654",
  "sb.branchTip": "\uBE0C\uB79C\uCE58: {branch}",
  "w.subdir": "\uC800\uC7A5\uC18C \uC548\uC758 \uD3F4\uB354(\uC120\uD0DD)",
  "w.subdirDesc": "\uBE44\uC6CC \uB450\uBA74 \uC800\uC7A5\uC18C \uC804\uCCB4\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4. \uC5EC\uB7EC \uBCF4\uAD00\uC18C\uAC00 \uC800\uC7A5\uC18C \uD558\uB098\uB97C \uD568\uAED8 \uC4F8 \uB54C\uCC98\uB7FC \uC774 \uBCF4\uAD00\uC18C\uB97C \uD55C \uD3F4\uB354\uC5D0 \uB450\uB824\uBA74 \uC9C0\uC815\uD558\uC138\uC694."
